import React, { PropsWithChildren } from 'react';

import {
  MeterBarChartDataProviderData,
  MeterBarChartDataProviderProps,
} from '../types/meter-bar-chart-internal.js';

export const MeterBarChartDataContext =
  React.createContext<MeterBarChartDataProviderData>(
    {} as MeterBarChartDataProviderData,
  );

export const MeterBarChartDataProvider = ({
  children,
  data,
}: PropsWithChildren<MeterBarChartDataProviderProps>) => (
  <MeterBarChartDataContext.Provider value={data}>
    {children}
  </MeterBarChartDataContext.Provider>
);

export const useMeterBarChartData = () =>
  React.useContext(MeterBarChartDataContext);
